PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE warehouses (
    warehouse_id INTEGER PRIMARY KEY AUTOINCREMENT,
    warehouse_code VARCHAR(20) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL,
    location_city VARCHAR(100) NOT NULL,
    total_capacity_sqm DECIMAL(10,2) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE warehouse_zones (
    zone_id INTEGER PRIMARY KEY AUTOINCREMENT,
    warehouse_id INTEGER NOT NULL,
    zone_code VARCHAR(30) NOT NULL UNIQUE,
    zone_name VARCHAR(100) NOT NULL,
    distance_to_dock_meters INTEGER NOT NULL,
    handling_type VARCHAR(50) DEFAULT 'STANDARD',
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(warehouse_id)
);
CREATE TABLE products_sku (
    sku_id INTEGER PRIMARY KEY AUTOINCREMENT,
    sku_code VARCHAR(30) NOT NULL UNIQUE,
    product_name VARCHAR(150) NOT NULL,
    category VARCHAR(50) NOT NULL,
    unit_weight_kg DECIMAL(6,2) NOT NULL,
    target_abc_class CHAR(1) DEFAULT 'B', -- 'A' (High 80%), 'B' (Mid 15%), 'C' (Low 5%)
    unit_price_jpy INTEGER NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE inventory_bins (
    bin_id INTEGER PRIMARY KEY AUTOINCREMENT,
    warehouse_id INTEGER NOT NULL,
    zone_id INTEGER NOT NULL,
    bin_code VARCHAR(30) NOT NULL UNIQUE,
    aisle_num INTEGER NOT NULL,
    rack_num INTEGER NOT NULL,
    shelf_level INTEGER NOT NULL,
    current_sku_id INTEGER,
    current_qty INTEGER NOT NULL DEFAULT 0,
    max_capacity_qty INTEGER NOT NULL,
    safety_stock_qty INTEGER NOT NULL DEFAULT 10,
    last_replenished_at TIMESTAMP,
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(warehouse_id),
    FOREIGN KEY (zone_id) REFERENCES warehouse_zones(zone_id),
    FOREIGN KEY (current_sku_id) REFERENCES products_sku(sku_id)
);
CREATE TABLE orders (
    order_id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_number VARCHAR(50) NOT NULL UNIQUE,
    customer_id VARCHAR(50) NOT NULL,
    order_timestamp TIMESTAMP NOT NULL,
    priority_level VARCHAR(20) DEFAULT 'STANDARD', -- STANDARD, EXPRESS, SAME_DAY
    status VARCHAR(30) NOT NULL,                  -- PENDING, ALLOCATED, PICKING, PACKED, SHIPPED
    destination_prefecture VARCHAR(50) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE order_items (
    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_id INTEGER NOT NULL,
    sku_id INTEGER NOT NULL,
    requested_qty INTEGER NOT NULL,
    allocated_bin_id INTEGER,
    fulfilled_qty INTEGER DEFAULT 0,
    unit_price_jpy INTEGER NOT NULL,
    FOREIGN KEY (order_id) REFERENCES orders(order_id),
    FOREIGN KEY (sku_id) REFERENCES products_sku(sku_id),
    FOREIGN KEY (allocated_bin_id) REFERENCES inventory_bins(bin_id)
);
CREATE TABLE fulfillment_tasks (
    task_id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_id INTEGER NOT NULL UNIQUE,
    assigned_picker_id VARCHAR(30) NOT NULL,
    order_received_at TIMESTAMP NOT NULL,
    pick_allocated_at TIMESTAMP NOT NULL,
    pick_started_at TIMESTAMP NOT NULL,
    pick_completed_at TIMESTAMP NOT NULL,
    pack_completed_at TIMESTAMP NOT NULL,
    shipped_at TIMESTAMP NOT NULL,
    picker_travel_meters INTEGER NOT NULL,
    picking_method VARCHAR(30) DEFAULT 'SINGLE_ORDER_DISCRETE', -- LEGACY: SINGLE_ORDER vs PROPOSED: BATCH_ZONE
    exception_flag INTEGER DEFAULT 0,                           -- 1 if stockout/mismatch encountered
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
);
CREATE INDEX idx_inventory_sku ON inventory_bins(current_sku_id);
CREATE INDEX idx_inventory_zone ON inventory_bins(zone_id);
CREATE INDEX idx_orders_status_timestamp ON orders(status, order_timestamp);
CREATE INDEX idx_order_items_sku ON order_items(sku_id);
CREATE INDEX idx_fulfillment_order ON fulfillment_tasks(order_id);
CREATE INDEX idx_fulfillment_timestamps ON fulfillment_tasks(order_received_at, shipped_at);
COMMIT;
